ValidationRule.errorConditionFormula:
(ISNEW() && BEGINS(Student_ID__c  , 'C') &&
(ISBLANK(TEXT(Come_From_Province__c)) ||
 ISBLANK(TEXT(Come_From_City__c))
)) ||
(ISNEW() == FALSE && BEGINS(Student_ID__c  , 'C') && 
 (
  (ISCHANGED(Come_From_Province__c) && ISBLANK(TEXT(Come_From_Province__c))) ||
  (ISCHANGED(Come_From_City__c) && ISBLANK(TEXT(Come_From_City__c)))
 )
)
